package io.cucumber.core.plugin;

import io.cucumber.plugin.EventListener;
import io.cucumber.plugin.event.*;
import io.cucumber.plugin.event.SnippetsSuggestedEvent.Suggestion;

import java.io.PrintStream;
import java.net.URI;
import java.util.*;
import java.util.function.Predicate;
import java.util.function.Supplier;
import java.util.stream.Collectors;

import static io.cucumber.core.exception.ExceptionUtils.printStackTrace;
import static java.util.Collections.emptyList;
import static java.util.stream.Collectors.joining;

/**
 * Outputs Teamcity services messages to std out.
 *
 * @see <a href=
 *      "https://www.jetbrains.com/help/teamcity/service-messages.html">TeamCity
 *      - Service Messages</a>
 */
public class TeamCityPlugin implements EventListener {

    private final TeamCityMessageFormatter formatter;
    private final TeamCityStepFormatter stepFormatter = new TeamCityStepFormatter();
    private final List<SnippetsSuggestedEvent> suggestions = new ArrayList<>();
    private final Map<URI, Collection<Node>> parsedTestSources = new HashMap<>();
    private List<Node> currentStack = new ArrayList<>();
    private TestCase currentTestCase;

    @SuppressWarnings("unused")
    public TeamCityPlugin() {
        this(System.out);
    }

    TeamCityPlugin(PrintStream out) {
        this.formatter = new TeamCityMessageFormatter(out);
    }

    @Override
    public void setEventPublisher(EventPublisher publisher) {
        publisher.registerHandlerFor(TestRunStarted.class, this::printTestRunStarted);
        publisher.registerHandlerFor(TestCaseStarted.class, this::printTestCaseStarted);
        publisher.registerHandlerFor(TestStepStarted.class, this::printTestStepStarted);
        publisher.registerHandlerFor(TestStepFinished.class, this::printTestStepFinished);
        publisher.registerHandlerFor(TestCaseFinished.class, this::printTestCaseFinished);
        publisher.registerHandlerFor(TestRunFinished.class, this::printTestRunFinished);
        publisher.registerHandlerFor(SnippetsSuggestedEvent.class, this::handleSnippetSuggested);
        publisher.registerHandlerFor(EmbedEvent.class, this::handleEmbedEvent);
        publisher.registerHandlerFor(WriteEvent.class, this::handleWriteEvent);
        publisher.registerHandlerFor(TestSourceParsed.class, this::handleTestSourceParsed);
    }

    private void handleTestSourceParsed(TestSourceParsed event) {
        parsedTestSources.put(event.getUri(), event.getNodes());
    }

    private void printTestRunStarted(TestRunStarted event) {
        String timestamp = formatter.extractTimeStamp(event);
        formatter.print(TeamCityMessageFormatter.TEMPLATE_ENTER_THE_MATRIX, timestamp);
        formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_RUN_STARTED, timestamp);
        formatter.print(TeamCityMessageFormatter.TEMPLATE_PROGRESS_COUNTING_STARTED, timestamp);
    }

    private void printTestCaseStarted(TestCaseStarted event) {
        TestCase testCase = event.getTestCase();
        URI uri = testCase.getUri();
        String timestamp = formatter.extractTimeStamp(event);
        Location location = testCase.getLocation();
        Predicate<Node> withLocation = candidate -> location.equals(candidate.getLocation());
        List<Node> path = parsedTestSources.get(uri).stream().map(node -> node.findPathTo(withLocation))
                .filter(Optional::isPresent).map(Optional::get).findFirst().orElse(emptyList());
        poppedNodes(path).forEach(node -> finishNode(timestamp, node));
        pushedNodes(path).forEach(node -> startNode(uri, timestamp, node));
        currentStack = path;
        currentTestCase = testCase;
        formatter.print(TeamCityMessageFormatter.TEMPLATE_PROGRESS_TEST_STARTED, timestamp);
    }

    private void startNode(URI uri, String timestamp, Node node) {
        Supplier<String> keyword = () -> node.getKeyword().orElse("Unknown");
        String name = node.getName().orElseGet(keyword);
        String location = uri + ":" + node.getLocation().getLine();
        formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_SUITE_STARTED, timestamp, location, name);
    }

    private void finishNode(String timestamp, Node node) {
        Supplier<String> keyword = () -> node.getKeyword().orElse("Unknown");
        String name = node.getName().orElseGet(keyword);
        formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_SUITE_FINISHED, timestamp, name);
    }

    private List<Node> poppedNodes(List<Node> newStack) {
        List<Node> nodes = new ArrayList<>(reversedPoppedNodes(currentStack, newStack));
        Collections.reverse(nodes);
        return nodes;
    }

    private List<Node> reversedPoppedNodes(List<Node> oldStack, List<Node> newStack) {
        for (int i = 0; i < oldStack.size() && i < newStack.size(); i++) {
            if (!oldStack.get(i).equals(newStack.get(i)))
                return oldStack.subList(i, oldStack.size());
        }
        if (newStack.size() < oldStack.size())
            return oldStack.subList(newStack.size(), oldStack.size());
        return emptyList();
    }

    private List<Node> pushedNodes(List<Node> newStack) {
        for (int i = 0; i < currentStack.size() && i < newStack.size(); i++) {
            if (!currentStack.get(i).equals(newStack.get(i)))
                return newStack.subList(i, newStack.size());
        }
        if (newStack.size() < currentStack.size())
            return emptyList();
        return newStack.subList(currentStack.size(), newStack.size());
    }

    private void printTestStepStarted(TestStepStarted event) {
        String timestamp = formatter.extractTimeStamp(event);
        formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_STARTED, timestamp,
            stepFormatter.extractLocation(event), stepFormatter.extractName(event.getTestStep()));
    }

    private void printTestStepFinished(TestStepFinished event) {
        String timestamp = formatter.extractTimeStamp(event);
        long duration = event.getResult().getDuration().toMillis();
        String name = stepFormatter.extractName(event.getTestStep());
        Throwable error = event.getResult().getError();
        switch (event.getResult().getStatus()) {
            case SKIPPED:
                formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_IGNORED, timestamp, duration,
                    error == null ? "Step skipped" : error.getMessage(), name);
                break;
            case PENDING:
                formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_FAILED, timestamp, duration, "Step pending",
                    error == null ? "" : error.getMessage(), name);
                break;
            case UNDEFINED:
                formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_FAILED, timestamp, duration, "Step undefined",
                    getSnippets(currentTestCase), name);
                break;
            case AMBIGUOUS:
            case FAILED:
                String details = printStackTrace(error);
                String message = error.getMessage();
                if (message == null) {
                    formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_FAILED, timestamp, duration, "Step failed",
                        details, name);
                    break;
                }
                ComparisonFailure comparison = ComparisonFailure.parse(message.trim());
                if (comparison == null) {
                    formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_FAILED, timestamp, duration, "Step failed",
                        details, name);
                    break;
                }
                formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_COMPARISON_FAILED, timestamp, duration,
                    "Step failed", details, comparison.getExpected(), comparison.getActual(), name);
                break;
            default:
                break;
        }
        formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_FINISHED, timestamp, duration, name);
    }

    private String getSnippets(TestCase testCase) {
        URI uri = testCase.getUri();
        Location location = testCase.getLocation();
        List<Suggestion> matching = suggestions.stream()
                .filter(s -> s.getUri().equals(uri) && s.getTestCaseLocation().equals(location))
                .map(SnippetsSuggestedEvent::getSuggestion).collect(Collectors.toList());
        if (matching.isEmpty())
            return "";
        StringBuilder result = new StringBuilder("You can implement this step");
        if (matching.size() > 1)
            result.append(" and ").append(matching.size() - 1).append(" other step(s)");
        result.append(" using the snippet(s) below:\n\n");
        result.append(matching.stream().map(Suggestion::getSnippets).flatMap(Collection::stream).distinct()
                .collect(joining("\n", "", "\n")));
        return result.toString();
    }

    private void printTestCaseFinished(TestCaseFinished event) {
        String timestamp = formatter.extractTimeStamp(event);
        formatter.print(TeamCityMessageFormatter.TEMPLATE_PROGRESS_TEST_FINISHED, timestamp);
        finishNode(timestamp, currentStack.remove(currentStack.size() - 1));
        currentTestCase = null;
    }

    private void printTestRunFinished(TestRunFinished event) {
        String timestamp = formatter.extractTimeStamp(event);
        formatter.print(TeamCityMessageFormatter.TEMPLATE_PROGRESS_COUNTING_FINISHED, timestamp);
        List<Node> emptyStack = new ArrayList<>();
        poppedNodes(emptyStack).forEach(node -> finishNode(timestamp, node));
        currentStack = emptyStack;
        Throwable error = event.getResult().getError();
        if (error != null) {
            String name = "Before All/After All";
            formatter.print(TeamCityMessageFormatter.TEMPLATE_BEFORE_ALL_AFTER_ALL_STARTED, timestamp, name);
            formatter.print(TeamCityMessageFormatter.TEMPLATE_BEFORE_ALL_AFTER_ALL_FAILED, timestamp,
                "Before All/After All failed", printStackTrace(error), name);
            formatter.print(TeamCityMessageFormatter.TEMPLATE_BEFORE_ALL_AFTER_ALL_FINISHED, timestamp, name);
        }
        formatter.print(TeamCityMessageFormatter.TEMPLATE_TEST_RUN_FINISHED, timestamp);
    }

    private void handleSnippetSuggested(SnippetsSuggestedEvent event) {
        suggestions.add(event);
    }

    private void handleEmbedEvent(EmbedEvent event) {
        String name = event.getName() == null ? "" : event.getName() + " ";
        formatter.print(TeamCityMessageFormatter.TEMPLATE_ATTACH_WRITE_EVENT,
            "Embed event: " + name + "[" + event.getMediaType() + " " + event.getData().length + " bytes]\n");
    }

    private void handleWriteEvent(WriteEvent event) {
        formatter.print(TeamCityMessageFormatter.TEMPLATE_ATTACH_WRITE_EVENT,
            "Write event:\n" + event.getText() + "\n");
    }
}

package io.cucumber.core.plugin;

import io.cucumber.plugin.event.HookTestStep;
import io.cucumber.plugin.event.PickleStepTestStep;
import io.cucumber.plugin.event.TestStep;
import io.cucumber.plugin.event.TestStepStarted;

import java.util.Locale;
import java.util.function.BiFunction;
import java.util.function.Function;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class TeamCityStepFormatter {
    private static final Pattern ANNOTATION_GLUE_CODE_LOCATION_PATTERN = Pattern.compile("^(.*)\\.(.*)\\([^:]*\\)");
    private static final Pattern LAMBDA_GLUE_CODE_LOCATION_PATTERN = Pattern.compile("^(.*)\\.(.*)\\(.*:.*\\)");

    String extractLocation(TestStepStarted event) {
        TestStep step = event.getTestStep();
        if (step instanceof PickleStepTestStep) {
            PickleStepTestStep pickle = (PickleStepTestStep) step;
            return pickle.getUri() + ":" + pickle.getStep().getLine();
        }
        if (step instanceof HookTestStep)
            return formatHookStepLocation((HookTestStep) step, javaTestLocationUri(), TestStep::getCodeLocation);
        return step.getCodeLocation();
    }

    private static BiFunction<String, String, String> javaTestLocationUri() {
        return (declaringClass, method) -> String.format("java:test://%s/%s", declaringClass, method);
    }

    String formatHookStepLocation(
            HookTestStep hook, BiFunction<String, String, String> format, Function<HookTestStep, String> fallback
    ) {
        Matcher matcher = ANNOTATION_GLUE_CODE_LOCATION_PATTERN.matcher(hook.getCodeLocation());
        if (matcher.matches())
            return format.apply(matcher.group(1), matcher.group(2));
        matcher = LAMBDA_GLUE_CODE_LOCATION_PATTERN.matcher(hook.getCodeLocation());
        if (matcher.matches()) {
            String declaringClass = matcher.group(1);
            int separator = declaringClass.lastIndexOf(".");
            String simpleName = separator == -1 ? declaringClass : declaringClass.substring(separator + 1);
            return format.apply(declaringClass, simpleName);
        }
        return fallback.apply(hook);
    }

    String getHookName(HookTestStep hook) {
        switch (hook.getHookType()) {
            case BEFORE:
                return "Before";
            case AFTER:
                return "After";
            case BEFORE_STEP:
                return "BeforeStep";
            case AFTER_STEP:
                return "AfterStep";
            default:
                return hook.getHookType().name().toLowerCase(Locale.US);
        }
    }

    String extractName(TestStep step) {
        if (step instanceof PickleStepTestStep)
            return ((PickleStepTestStep) step).getStep().getText();
        if (step instanceof HookTestStep) {
            HookTestStep hook = (HookTestStep) step;
            return formatHookStepLocation(hook,
                (declaringClass, method) -> String.format("%s(%s)", getHookName(hook), method), this::getHookName);
        }
        return "Unknown step";
    }
}
